'use strict';
const $=id=>document.getElementById(id);
const recipes={grain:{name:'Soft grains',ratio:7,blend:0,explain:'A heating and cooking sequence with no blade blending. Recognizable grains remain. The modeled cooking time is not shortened to preserve grain size.'},gentle:{name:'Gentle porridge',ratio:8,blend:45,explain:'The same cooking foundation is followed by brief, intermittent blending. Some particles become smaller, while some grain texture remains.'},smooth:{name:'Smooth paste',ratio:8,blend:150,explain:'After cooking, a longer continuous blending stage reduces particle size. It is a different process from stopping porridge early.'}};
const key='porridge-redesign-preferences-v2';let saved=[],storageAvailable=true;
try{saved=JSON.parse(localStorage.getItem(key)||'[]');if(!Array.isArray(saved))saved=[];saved=saved.filter(x=>x&&typeof x.name==='string'&&recipes[x.texture]&&[1,2].includes(x.servings)&&['thick','balanced','loose'].includes(x.thickness)).slice(0,20);}catch(e){saved=[];storageAvailable=false;}
let state={page:'choose',texture:'gentle',servings:1,thickness:'balanced',ingredient:'rice',weight:0,rice:0,water:0,lid:false,status:'ready',temp:22,elapsed:0,stage:0,heater:false,motor:false,ground:0,notice:''};
function plan(){const r=recipes[state.texture],rice=40*state.servings,ratio=r.ratio+({thick:-1,balanced:0,loose:1}[state.thickness]),water=rice*ratio;const stages=[{name:'Heat',seconds:360+120*(state.servings-1),target:95,blend:false},{name:'Cook & soften',seconds:900,target:98,blend:false}];if(r.blend)stages.push({name:state.texture==='gentle'?'Brief pulses':'Blend smooth',seconds:r.blend,target:92,blend:true});return {rice,water,ratio,stages,total:stages.reduce((a,s)=>a+s.seconds,0)};}
function format(n){n=Math.max(0,Math.ceil(n));return Math.floor(n/60)+':'+String(n%60).padStart(2,'0');}
function busy(){return state.status==='running';}
function target(){return plan()[state.ingredient];}
function validWeight(){return Number.isFinite(state.weight)&&state.weight>=0&&state.weight===target();}
function resetBatch(){state.rice=0;state.water=0;state.weight=0;state.ingredient='rice';state.status='ready';state.temp=22;state.elapsed=0;state.stage=0;state.heater=false;state.motor=false;state.ground=0;state.lid=false;state.notice='';$('saveFeedback').textContent='';$('rating').value='untested';}
function show(page){state.page=page;render();}
function particleSetup(){const box=$('particles');box.innerHTML='';for(let i=0;i<26;i++){let el=document.createElement('i');el.className='particle';el.style.left=(12+i*31%75)+'%';el.style.top=(15+i*19%60)+'%';el.style.animationDelay=(-i*.1)+'s';box.appendChild(el);}}
function render(){const p=plan(),r=recipes[state.texture];['choose','weigh','cook'].forEach((x,i)=>{$(x).hidden=state.page!==x;$('nav'+(i+1)).className=state.page===x?'active':'';});document.querySelectorAll('[data-texture]').forEach(el=>{const on=el.dataset.texture===state.texture;el.classList.toggle('selected',on);el.setAttribute('aria-pressed',String(on));});$('servings').value=String(state.servings);$('thickness').value=state.thickness;
 $('recipeSummary').textContent=`${p.rice} g rice + ${p.water} g water · ratio 1:${p.ratio} by weight · ${format(p.total)} modeled cooking time. Illustrative values.`;$('explanation').textContent=r.explain+' Two servings lengthen the modeled heating stage, rather than simply doubling all cooking time.';
 const isRice=state.ingredient==='rice';$('weighTitle').textContent=isRice?'First, add rice.':'Now, add water.';$('weighHelp').textContent=isRice?'The empty bowl is tared to zero. Add the rice first so its weight can be recorded separately.':`${state.rice} g rice recorded. Scale tared to zero; this reading measures added water only.`;$('currentWeight').textContent=Number.isFinite(state.weight)?state.weight:'—';$('targetWeight').textContent=target();$('weight').value=Number.isFinite(state.weight)?state.weight:'';$('weightProgress').style.width=Math.min(100,Math.max(0,state.weight/target()*100))+'%';$('confirmWeight').disabled=!validWeight();$('confirmWeight').textContent=isRice?'Confirm rice & tare scale →':'Confirm water & review →';
 $('weightFeedback').textContent=!Number.isFinite(state.weight)||state.weight<0?'Enter a non-negative amount.':state.weight>target()?`${state.weight-target()} g over target. In this simulation, reduce this ingredient’s reading before continuing.`:state.weight===target()?'Target reached. Confirm to continue.':`Add ${target()-state.weight} g more ${state.ingredient}.`;
 $('scaleReading').textContent=(state.page==='weigh'?(Number.isFinite(state.weight)?state.weight:'—'):state.rice+state.water)+' g';$('scaleCaption').textContent=state.page==='weigh'?(isRice?'Rice only · empty bowl tared':'Water only · rice weight recorded'):'Total ingredients in bowl';$('machine').className='machine'+(state.lid?' aligned':'')+(state.heater?' heating':'')+(state.motor?' blending':'');$('machineMode').textContent=r.name.toUpperCase();$('machineStage').textContent=state.page==='choose'?'Choose your preference':state.page==='weigh'?'Add '+state.ingredient:state.status==='running'?p.stages[state.stage].name:state.status==='complete'?'Program complete':state.status==='stopped'?'Stopped early':'Awaiting your Start';
 let completed=p.stages.slice(0,state.stage).reduce((a,s)=>a+s.seconds,0)+state.elapsed;if(state.status==='complete')completed=p.total;const left=p.total-completed;$('remaining').textContent=format(left);$('digits').textContent=state.page==='cook'?format(left):state.page==='weigh'?'WEIGH':'READY';$('cookProgress').style.width=completed/p.total*100+'%';$('cookSummary').textContent=`${r.name} · ${state.servings} serving${state.servings===2?'s':''} · ${state.rice} g rice + ${state.water} g water. ${format(p.total)} total, illustrative.`;$('cookTitle').textContent=busy()?'Your recipe is in motion.':state.status==='complete'?'Program complete.':state.status==='stopped'?'Stopped, not completed.':'Ready to begin.';
 $('lidState').textContent=state.lid?'Aligned · interlock satisfied':'Not aligned · starting blocked';$('align').textContent=state.lid?'Unlock lid ↻':'Align lid ↻';$('lid').setAttribute('aria-pressed',String(state.lid));$('start').disabled=!state.lid||busy()||state.status==='complete'||state.status==='stopped';$('stop').disabled=!busy();$('newBatch').disabled=busy();$('temp').textContent=Math.round(state.temp)+'°';$('sensorInfo').textContent=Math.round(state.temp)+'°C · simulated';$('heatInfo').textContent=state.heater?'Heating':'Off';$('bladeInfo').textContent=state.motor?(state.texture==='gentle'?'Brief pulse':'Continuous blending'):'Off';$('stages').innerHTML=p.stages.map((s,i)=>`<span class="${busy()&&state.stage===i?'active':''}">${i+1}. ${s.name} (${format(s.seconds)})</span>`).join('');$('processStatus').textContent=state.notice||'Align the lid, then press Start. Nothing starts automatically.';$('saveArea').hidden=state.status!=='complete';
 const water=state.water+(state.page==='weigh'&&!isRice?Math.max(0,state.weight||0):0),rice=state.rice+(state.page==='weigh'&&isRice?Math.max(0,state.weight||0):0);$('water').style.height=Math.min(205,water*.3)+'px';$('particles').style.opacity=rice>0?'1':'0';document.querySelectorAll('.particle').forEach((el,i)=>{el.style.scale=String(1-state.ground*(state.texture==='gentle'?(i%3===0?.1:.45):.8));});
}
function tick(dt){if(!busy())return;const p=plan();let remaining=dt*Number($('speed').value);while(remaining>0&&busy()){const s=p.stages[state.stage],step=Math.min(remaining,s.seconds-state.elapsed);state.elapsed+=step;remaining-=step;state.heater=!s.blend&&state.temp<s.target;if(state.heater)state.temp=Math.min(s.target,state.temp+step*.25);else state.temp=Math.max(22,state.temp-step*.008);state.motor=s.blend&&(state.texture==='smooth'||Math.floor(state.elapsed/10)%2===0);if(state.motor)state.ground=Math.min(1,state.ground+step/(recipes[state.texture].blend*.6));if(state.elapsed>=s.seconds){state.stage++;state.elapsed=0;if(state.stage>=p.stages.length){state.status='complete';state.heater=false;state.motor=false;state.notice='The modeled program has ended. Evaluate the actual result before saving it as a preference; completion does not measure food texture or safety.';}}}render();}
function align(){state.lid=!state.lid;if(busy()&&!state.lid)stop('Lid alignment lost. Heating and blending stopped; contents remain hot. Prepare a new batch to restart this demo.');else render();}
function stop(message){state.status='stopped';state.heater=false;state.motor=false;state.notice=message||'You stopped the process. Heater and blades are off; contents remain hot. This batch is not marked complete.';render();}
function listSaved(){const box=$('savedList');box.innerHTML='';$('savedCount').textContent=`(${saved.length})`;if(!saved.length)box.textContent='No saved preferences yet. Complete a demo cycle to save one.';saved.forEach((s,i)=>{const row=document.createElement('div');row.className='saved-item';const desc=document.createElement('div'),name=document.createElement('strong'),info=document.createElement('small');name.textContent=s.name;info.textContent=`${recipes[s.texture].name} · ${s.servings} serving(s) · ${s.thickness} · ${s.rating==='liked'?'liked result':'not confirmed as preferred'}`;desc.append(name,info);const actions=document.createElement('div'),load=document.createElement('button'),remove=document.createElement('button');load.textContent='Load';remove.textContent='Delete';load.addEventListener('click',()=>{resetBatch();state.texture=s.texture;state.servings=s.servings;state.thickness=s.thickness;show('choose');});remove.addEventListener('click',()=>{saved.splice(i,1);persist();listSaved();});actions.append(load,remove);row.append(desc,actions);box.appendChild(row);});}
function persist(){try{localStorage.setItem(key,JSON.stringify(saved));return true;}catch(e){storageAvailable=false;return false;}}
document.querySelectorAll('[data-texture]').forEach(el=>el.addEventListener('click',()=>{state.texture=el.dataset.texture;render();}));$('servings').addEventListener('change',()=>{state.servings=Number($('servings').value);render();});$('thickness').addEventListener('change',()=>{state.thickness=$('thickness').value;render();});$('toWeigh').addEventListener('click',()=>{resetBatch();show('weigh');});$('weight').addEventListener('input',()=>{state.weight=$('weight').value===''?NaN:Number($('weight').value);render();});$('addSmall').addEventListener('click',()=>{state.weight=(Number.isFinite(state.weight)?Math.max(0,state.weight):0)+10;render();});$('fillTarget').addEventListener('click',()=>{state.weight=target();render();});$('clearWeight').addEventListener('click',()=>{state.weight=0;render();});$('confirmWeight').addEventListener('click',()=>{if(!validWeight())return;if(state.ingredient==='rice'){state.rice=state.weight;state.ingredient='water';state.weight=0;render();}else{state.water=state.weight;show('cook');}});$('backChoose').addEventListener('click',()=>{resetBatch();show('choose');});$('newBatch').addEventListener('click',()=>{if(busy())return;resetBatch();show('choose');});$('align').addEventListener('click',align);$('lid').addEventListener('click',align);$('start').addEventListener('click',()=>{if(state.page!=='cook'||state.status!=='ready'||!state.lid||state.rice!==plan().rice||state.water!==plan().water)return;state.status='running';state.notice='Follow the stages below. The timer is a simulated program estimate, not a texture sensor.';render();});$('stop').addEventListener('click',()=>{if(busy())stop();});$('rating').addEventListener('change',()=>{$('ratingHelp').textContent={untested:'A completed program is not proof of the desired texture.',liked:'Save this as a preference to try again. Ingredients and results can still vary.',thick:'For a future batch, explore Looser under the consistency details.',fine:'For a future batch, try Soft grains or Gentle porridge to reduce blending.',firm:'Firm grains relate to cooking and hydration, not just blending. This prototype does not validate cooking times.'}[$('rating').value];});$('save').addEventListener('click',()=>{if(state.status!=='complete')return;const name=$('preferenceName').value.trim();if(!name){$('saveFeedback').textContent='Give this preference a name first.';return;}if(saved.length>=20){$('saveFeedback').textContent='You have 20 preferences. Delete one before saving another.';return;}saved.push({name,texture:state.texture,servings:state.servings,thickness:state.thickness,rating:$('rating').value});const ok=persist();listSaved();$('saveFeedback').textContent=ok?'Saved in this browser. Find it under My saved preferences.':'Saved for this session only; browser storage is unavailable.';});
particleSetup();listSaved();render();setInterval(()=>tick(.1),100);
